void buttonStyle::setStrSheet(QString str1, QString str2, QString str3)
{
    btnStrSheet = QString(".QPushButton{\
                          background-color: rgba(%1);\
                          color: #FFFFFF;\
                          border-radius: 4px;\
                          padding: 2px;\
                          }\
                          .QPushButton:hover {\
                          background-color: rgba(%2);\
                          }\
                          .QPushButton:pressed {\
                          background-color: rgba(%3);\
                          }\
                          QWidget#widget_2{\
                          border:1px solid #E4E8EB;\
                          border-radius: 10px;\
                          }").arg(str1).arg(str2).arg(str3);
}
